import{_ as i,C as a,o as s,c as n,E as r,a2 as o}from"./chunks/framework.Cm6XCzck.js";const l="/joinwell52/assets/covers/daily-2026-08-19-governance-to-fault-testing-en.png",b=JSON.parse('{"title":"Don’t Trust an All-Green Demo: How Fault Injection Exposes an Unreliable AI Agent Dispatcher","description":"","frontmatter":{"title":"Don’t Trust an All-Green Demo: How Fault Injection Exposes an Unreliable AI Agent Dispatcher","date":"2026-08-19","column":"open-source-engineering","category":"daily","article_type":"project-research","edition":"research-center","research_question":"How should an AI agent dispatcher be tested through governance invariants, fault locations, and observable verdicts?","summary":"Reliability tests should combine one rule that must survive, one injected fault, and one observable verdict instead of treating a successful UI path as proof.","item_id":"MANUAL-20260819-FAULT-INJECTION","lifecycle":"Published","cover":"/assets/covers/daily-2026-08-19-agent-dispatch-fault-injection-cover.png","evidence_status":"Completed","citation_status":"Completed","editing_status":"Completed","publication_authorized":true,"sources":["research/manual-runs/2026-08-19-guided-article-pipeline-round1/02-source-register.md","research/manual-runs/2026-08-19-guided-article-pipeline-round1/02-fact-claim-matrices.md","research/manual-runs/2026-08-19-guided-article-pipeline-round1/02-article-briefs.md","research/manual-runs/2026-08-19-guided-article-pipeline-round1/02-experiment-run-log.md","research/manual-runs/2026-08-19-guided-article-pipeline-round1/03-independent-final-package-review-round2.md"]},"headers":[],"relativePath":"en/engineering/2026-08-19-agent-dispatch-fault-injection.md","filePath":"en/engineering/2026-08-19-agent-dispatch-fault-injection.md","lastUpdated":1787125010000}'),d={name:"en/engineering/2026-08-19-agent-dispatch-fault-injection.md"};function c(h,e,p,u,m,g){const t=a("ArticleCover");return s(),n("div",null,[r(t,{image:"/assets/covers/daily-2026-08-19-agent-dispatch-fault-injection-cover.png",kicker:"Open-source Engineering · Project Research",title:"Don’t Trust an All-Green Demo: How Fault Injection Exposes an Unreliable AI Agent Dispatcher",summary:"Reliability tests should combine one rule that must survive, one injected fault, and one observable verdict instead of treating a successful UI path as proof.",version:"MANUAL-20260819-FAULT-INJECTION",status:"Independent Editorial PASS · 2026-08-19",languageHref:"/zh/engineering/2026-08-19-agent-dispatch-fault-injection",languageLabel:"中文"}),e[0]||(e[0]=o('<h1 id="don-t-trust-an-all-green-demo-how-fault-injection-exposes-an-unreliable-ai-agent-dispatcher" tabindex="-1">Don’t Trust an All-Green Demo: How Fault Injection Exposes an Unreliable AI Agent Dispatcher <a class="header-anchor" href="#don-t-trust-an-all-green-demo-how-fault-injection-exposes-an-unreliable-ai-agent-dispatcher" aria-label="Permalink to &quot;Don’t Trust an All-Green Demo: How Fault Injection Exposes an Unreliable AI Agent Dispatcher&quot;">​</a></h1><p><strong>Series map:</strong> begin with <a href="/joinwell52/en/engineering/2026-08-19-taskbook-to-task-graph">the long-requirement work graph</a>. This article asks what remains true after a fault; finish with <a href="/joinwell52/en/digital-employee/2026-08-19-local-runtime-mobile-control">local execution and mobile control</a>.</p><h2 id="in-ten-seconds" tabindex="-1">In ten seconds <a class="header-anchor" href="#in-ten-seconds" aria-label="Permalink to &quot;In ten seconds&quot;">​</a></h2><p>Organize reliability tests as <strong>one rule that must never break × one injected fault × one observable verdict</strong>. The article delivers six defensive rules, four fault families, and a 12-case checklist that can become a Runtime test plan.</p><p>The easiest multi-agent demo is a happy path: create a TASK, let an agent claim it, write a REPORT, and show “done” in the UI.</p><p>One successful run says almost nothing about the harder system. What happens when a watcher emits the same file event twice? If the dispatch record is durable but the model session never starts, will restart launch duplicate work? If one task appears in both <code>active/</code> and <code>review/</code>, which location wins? If a dependency prevents a test from running, does the dashboard still say PASS?</p><p>Reliability testing begins with facts that must survive every interleaving, not with buttons on a page.</p><blockquote><p><strong>Do not only ask whether the workflow completed. Ask which invariants remain true when failure lands on every commit boundary.</strong></p></blockquote><h2 id="start-from-protocol-invariants-without-repeating-the-protocol-tutorial" tabindex="-1">Start from protocol invariants without repeating the protocol tutorial <a class="header-anchor" href="#start-from-protocol-invariants-without-repeating-the-protocol-tutorial" aria-label="Permalink to &quot;Start from protocol invariants without repeating the protocol tutorial&quot;">​</a></h2><p><a href="https://github.com/joinwell52-AI/FCoP/blob/a859e6747fe6e5e2d686e0114c77774726d7f748/spec/fcop-v3-spec.md" target="_blank" rel="noreferrer">FCoP v3</a> defines TASK, REPORT, ISSUE, and REVIEW artifacts, plus the collaboration semantics in which location represents current state and events preserve transition history. The previous article, <a href="/joinwell52/en/engineering/2026-08-18-fcop-file-state-machine">“Files, Paths, and Events: Implementing and Testing the FCoP Collaboration State Machine”</a>, covers protocol transitions and atomic commit in full; here they are only inputs to Runtime testing. <a href="https://github.com/joinwell52-AI/FCoP/blob/a859e6747fe6e5e2d686e0114c77774726d7f748/adr/ADR-0038-fcop-boundary-charter.md" target="_blank" rel="noreferrer">ADR-0038</a> narrows the boundary: the protocol externalizes and coordinates work; it does not execute tasks or own model sessions and global orchestration.</p><p>CodeFlowMu Runtime owns file observation, task parsing, dependency checks, agent selection, session startup, dispatch commit, and recovery. Testing therefore needs layers:</p><table tabindex="0"><thead><tr><th>Layer</th><th>What it must establish</th><th>Typical failure</th></tr></thead><tbody><tr><td>Protocol/artifact</td><td>Identity, provenance, legal state, history, authority</td><td>Duplicate identity, illegal transition, history gap</td></tr><tr><td>Storage commit</td><td>No partial canonical write; bounded recovery</td><td>Temp residue, rename failure, weak durability</td></tr><tr><td>Runtime observation</td><td>Repeated events and reconciliation do not duplicate effects</td><td>Watcher jitter, missed event, double scan</td></tr><tr><td>Dispatch/session</td><td>Dependencies, busy state, two-phase dispatch, crash recovery</td><td>Double dispatch, orphan session</td></tr><tr><td>Governance</td><td>A REPORT does not confer acceptance; failures remain visible</td><td>Self-approval, NOT RUN reported as PASS</td></tr></tbody></table><p>A single end-to-end test collapses these layers. When it fails, “the workflow did not finish” cannot tell you whether the defect belongs to protocol semantics, storage, observation, or the session host.</p><p><img src="'+l+`" alt="The layered relationship among TMPA governance semantics, the FCoP file-protocol projection, CodeFlowMu runtime responsibility, and fault evidence"></p><p><em>Figure 1. TMPA defines what should hold, FCoP specifies how it is expressed, and CodeFlowMu implements how it runs. TMPA C01–C14 conformance evidence and this article&#39;s 12 product-fault scenarios cannot substitute for one another. Source: TMPA Core S1.0, FCoP v3, current CodeFlowMu code, and the 2026-08-19 experiment record.</em></p><h2 id="six-defensive-rules-worth-encoding-first" tabindex="-1">Six defensive rules worth encoding first <a class="header-anchor" href="#six-defensive-rules-worth-encoding-first" aria-label="Permalink to &quot;Six defensive rules worth encoding first&quot;">​</a></h2><p>Regardless of language or storage engine, start with six rules that a fault must never be allowed to break:</p><ol><li><strong>A task identity never means two jobs:</strong> duplicates are reported, not overwritten.</li><li><strong>A task cannot have split-state personality:</strong> two current locations are preserved as a conflict, not resolved by traversal order.</li><li><strong>History is an append-only ledger:</strong> rejection, failure, retry, and recovery remain visible.</li><li><strong>Every model call is attributable:</strong> it maps to a task version, execution attempt, time-bounded claim, and host decision.</li><li><strong>No permit, no start:</strong> unmet dependencies, a busy agent, or an unapproved gate prevents session startup.</li><li><strong>Restart never guesses:</strong> persistent artifacts and explicit execution records decide retry, rework, continue, or stop.</li></ol><p><a href="https://joinwell52-ai.github.io/joinwell52/en/publications/tmpa-core-specification-s1.0" target="_blank" rel="noreferrer">TMPA Core S1.0</a> supplies the identity, state, conflict, history, and recovery baseline. CodeFlowMu adds product responsibilities for watchers, dependencies, dispatch attempts, sessions, and time-bounded claims. The combination produces the Runtime test coordinates; the product-specific half is not a Core requirement.</p><p>Core also requires a deterministic Reader to produce a byte-equivalent canonical result for the same final source set and fixed Profile. Determinism here does not mean every timeline is identical. It means directory traversal order cannot change the governance verdict when the evidence is the same.</p><h2 id="why-file-coordination-still-needs-governance-semantics" tabindex="-1">Why file coordination still needs governance semantics <a class="header-anchor" href="#why-file-coordination-still-needs-governance-semantics" aria-label="Permalink to &quot;Why file coordination still needs governance semantics&quot;">​</a></h2><p>Putting Markdown files in directories is a storage technique, not a reliability model. A filesystem still permits duplicate sources, concurrent writers, torn updates, ambiguous locations, and evidence that disappears under an overwrite. The useful question is not “Can agents exchange files?” but “Which facts must remain true when those exchanges fail?”</p><p>TMPA Core supplies five constraints that give the file projection engineering meaning:</p><ol><li><strong>Stable identity and provenance.</strong> A governed object needs a stable identity, source relation, and accountable role. Two sources declaring the same task identity are a conflict to preserve, not an invitation to let the last writer win.</li><li><strong>Lifecycle and acceptance stay separate.</strong> A task location may represent its current collaboration state, while a REPORT records an execution claim and an authorized decision records acceptance. One field called <code>done</code> cannot safely compress all three.</li><li><strong>Published objects are immutable; history remains reconstructable.</strong> Rejection, failure, retry, and recovery append new evidence. They do not rewrite the past into a cleaner story.</li><li><strong>Conflict is a result.</strong> When readers find two current locations or incompatible sources, they report the ambiguity and stop the affected transition. Traversal order, confidence, or a model guess must not silently manufacture consensus.</li><li><strong>Recovery comes from durable evidence.</strong> A fresh reader must rebuild responsibility, lifecycle, unresolved dependencies, failures, and recovery relations without access to the previous agent&#39;s hidden reasoning.</li></ol><p>FCoP projects part of those semantics into TASK, REPORT, ISSUE, REVIEW, lifecycle locations, and transition events. CodeFlowMu then assumes the product responsibilities that a protocol does not: observing files, checking dependencies, managing attempts and sessions, enforcing time-bounded authority, and choosing a recovery policy.</p><p>That hierarchy also limits what a test result proves. TMPA C01–C14 check conformance behavior for an exact Core bundle. The 12 scenarios later in this article target concrete CodeFlowMu storage, observation, dispatch, and test-oracle failures. Neither suite can stand in for the other, and the 12 scenarios are a test plan—not a claim that all twelve already pass.</p><h2 id="storage-faults-atomic-rename-is-a-commit-point-not-a-universal-guarantee" tabindex="-1">Storage faults: atomic rename is a commit point, not a universal guarantee <a class="header-anchor" href="#storage-faults-atomic-rename-is-a-commit-point-not-a-universal-guarantee" aria-label="Permalink to &quot;Storage faults: atomic rename is a commit point, not a universal guarantee&quot;">​</a></h2><p>A common file commit is: write a uniquely named temporary file, flush its contents, then replace/rename the destination. POSIX <code>rename()</code> provides atomic name replacement under its defined conditions, which makes it useful as an observable commit point.</p><p>Keep the boundary narrow:</p><ul><li>Do not assume atomicity across mounts.</li><li><code>fsync(file)</code> is not automatically durable directory metadata after power loss.</li><li>Windows sharing, antivirus scanning, or transient path disappearance can yield EPERM/ENOENT.</li><li>A successful rename does not make downstream business effects exactly-once.</li><li>A file lock does not automatically eliminate deadlock or every race.</li></ul><p>On 2026-08-19, we ran the current CodeFlowMu <a href="https://github.com/joinwell52-AI/CodeFlowMu-open/blob/ed5634c718b9e238c44bb70851020c9793546fe6/packages/codeflowmu-runtime/src/_internal/__tests__/atomic-write.test.ts" target="_blank" rel="noreferrer">atomic-write test file</a> in the local working copy: <strong>9 tests passed</strong>. That supports the limited claim that the tested temp-file, replacement, and bounded-retry branches passed in this environment. It does not support “safe on every filesystem” or “exactly-once execution.”</p><p>A useful harness places faults between storage steps:</p><div class="language-ts vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">ts</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// Illustrative interface, not a published CodeFlowMu API.</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">await</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> scenario</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">({ seed: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">42017</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> })</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  .</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">given</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">taskIn</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;active&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;TASK-001&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">))</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  .</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">inject</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;after-temp-write&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">error</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;EPERM&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">), { times: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">2</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> })</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  .</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">inject</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;after-replace-before-source-unlink&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">crash</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">())</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  .</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">restartRuntime</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">()</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  .</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">expect</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">oneCanonicalLocation</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;TASK-001&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">))</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  .</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">expect</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">historyExplainsCurrentState</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;TASK-001&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">))</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  .</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">expect</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">noUnboundedRetry</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">());</span></span></code></pre></div><p>The API shape is unimportant. The seed, injection point, error count, restart, and final verdict must be reproducible.</p><h2 id="event-faults-a-watcher-notification-is-not-a-business-fact" tabindex="-1">Event faults: a watcher notification is not a business fact <a class="header-anchor" href="#event-faults-a-watcher-notification-is-not-a-business-fact" aria-label="Permalink to &quot;Event faults: a watcher notification is not a business fact&quot;">​</a></h2><p>Filesystem watchers may duplicate, merge, reorder, or miss transient notifications. A watcher event should therefore mean “re-read durable facts,” not “dispatch one task.”</p><p>Test duplicate observation paths together: emit two identical watcher events while periodic reconciliation finds the same TASK. Multiple observations are acceptable; only one constrained business commit is. The implementation may use a deduplication key, task revision, dispatch-intent record, or idempotent store. The test should specify the result rather than turn one lock design into a standard.</p><p>Also test a missed event: suppress the watcher completely and run reconciliation. The persistent task must still be discovered. Otherwise an optimization has quietly become the only fact-ingestion path.</p><h2 id="dispatch-faults-test-attempt-and-lease-commit-boundaries" tabindex="-1">Dispatch faults: test attempt and lease commit boundaries <a class="header-anchor" href="#dispatch-faults-test-attempt-and-lease-commit-boundaries" aria-label="Permalink to &quot;Dispatch faults: test attempt and lease commit boundaries&quot;">​</a></h2><p>CodeFlowMu&#39;s current <a href="https://github.com/joinwell52-AI/CodeFlowMu-open/blob/ed5634c718b9e238c44bb70851020c9793546fe6/packages/codeflowmu-runtime/src/scheduler/DispatchAttemptStore.ts" target="_blank" rel="noreferrer"><code>DispatchAttemptStore</code></a> persists <code>offered</code>, <code>claimed</code>, <code>running</code>, and terminal states, together with attempt, lease, session ID, and idempotency key. The existing <code>TaskDispatcher.twoPhaseDispatch.test.ts</code> mainly covers trusted and unknown routes, repeated holds, dependency blocking, explicit release, and <code>session_started</code>. It does <strong>not</strong> directly inject the two crash windows below.</p><p>The commit sequence that still needs fault injection is:</p><ol><li>Persist an intent bound to task revision, target agent, and rationale.</li><li>Start the model session.</li><li>Commit the external session identity or a failure record.</li></ol><p>The target contract is: after a crash following step 1, restart sees “attempt without session”; after session startup but before step 3, external session identity or an idempotency key prevents a blind second launch. These are test requirements in this article, not a claim that the current crash paths have already been verified.</p><p>This is still not exactly-once. For external APIs, Git pushes, payments, or other irreversible effects, a more realistic contract is at-least-once attempt, domain idempotency key, visible duplicates, and human-decidable recovery.</p><p>Busy agents and dependencies are fault inputs too. An unknown TASK source, a busy target agent, an incomplete parent, an unapproved gate, and simultaneous explicit wake plus automatic scan must all be tested instead of excluded by fixtures.</p><h2 id="pass-fail-and-not-run-are-different-facts" tabindex="-1">PASS, FAIL, and NOT RUN are different facts <a class="header-anchor" href="#pass-fail-and-not-run-are-different-facts" aria-label="Permalink to &quot;PASS, FAIL, and NOT RUN are different facts&quot;">​</a></h2><p>Our current rerun produced a more useful record than an all-green screenshot. Exact commands, environment, exit codes, and raw output are preserved in the <a href="https://github.com/joinwell52-AI/joinwell52/blob/main/research/manual-runs/2026-08-19-guided-article-pipeline-round1/02-experiment-run-log.md" target="_blank" rel="noreferrer">experiment run log</a>:</p><ul><li>Atomic-write tests: 9/9 passed.</li><li>LAN address tests: 5/5 passed.</li><li>Long-horizon planning tests did not load because <code>yaml</code> was missing.</li><li>Two-phase dispatch tests did not load because <code>@cursor/sdk</code> was missing.</li><li>The open-edition mobile-publication boundary test ran and failed because current permission semantics no longer match the older test contract. Exact identifiers and the raw assertion diff remain in the experiment log; the public engineering lesson is that implementation, user-facing permission language, and regression tests must move together.</li></ul><p>Under Core S1.0, an environment or infrastructure failure that prevents the test body from running is <strong>NOT RUN</strong>, not PASS and not automatically a product FAIL. The PWA case is a genuine executed <strong>FAIL</strong>, but its semantic classification remains open: did the implementation intentionally migrate the contract and leave a stale test, or did it diverge from the approved contract? A test detects drift; it does not possess product authority to choose the contract.</p><blockquote><p><strong>A trustworthy test system must expose product defects, test-environment gaps, and stale tests as distinct conditions.</strong></p></blockquote><h2 id="a-minimum-12-case-fault-injection-set" tabindex="-1">A minimum 12-case fault-injection set <a class="header-anchor" href="#a-minimum-12-case-fault-injection-set" aria-label="Permalink to &quot;A minimum 12-case fault-injection set&quot;">​</a></h2><table tabindex="0"><thead><tr><th>#</th><th>Scenario</th><th>Minimum verdict</th></tr></thead><tbody><tr><td>1</td><td>Two sources declare one TASK ID</td><td>Report conflict; do not overwrite</td></tr><tr><td>2</td><td>One TASK exists in two lifecycle directories</td><td>Preserve the dual-location conflict</td></tr><tr><td>3</td><td>Crash during temp write</td><td>Canonical file remains readable; temp can be cleaned</td></tr><tr><td>4</td><td>Repeated EPERM/ENOENT on replace</td><td>Bounded retry; final failure remains visible</td></tr><tr><td>5</td><td>Duplicate watcher event</td><td>Repeat observation, not business commit</td></tr><tr><td>6</td><td>Missed watcher event; reconciliation only</td><td>Durable task is eventually found</td></tr><tr><td>7</td><td>Target agent is busy</td><td>No double dispatch; record the block</td></tr><tr><td>8</td><td>Dependency or gate is unmet</td><td>Do not start a session</td></tr><tr><td>9</td><td>Crash after dispatch intent</td><td>Restart recognizes intent without session</td></tr><tr><td>10</td><td>Crash after session start, before commit</td><td>Avoid blind duplicate start through identity/idempotency</td></tr><tr><td>11</td><td>REPORT is replayed</td><td>Preserve history; do not upgrade acceptance</td></tr><tr><td>12</td><td>Test dependency is missing</td><td>Report NOT RUN with environment evidence</td></tr></tbody></table><p>Twelve is not an official specification number or a certification suite. It is a minimum transition from demo testing to engineering testing. Performance, load, longevity, security, cross-platform, cross-filesystem, and real-process termination tests still remain.</p><p>The public <a href="https://apple.github.io/foundationdb/testing.html" target="_blank" rel="noreferrer">FoundationDB testing material</a> shows the mature version of the idea: deterministic simulation, fault injection, and reproducible seeds can turn rare interleavings into repeatable experiments. Its results do not transfer to CodeFlowMu. Its method does: random exploration can be broad, but failure reproduction must be narrow.</p><p>The purpose of testing a file-based multi-agent Runtime is not to prove that “files are reliable.” It is to prove that when files, events, processes, and agents can all fail, the system can still explain the current facts, incomplete actions, and the next authority allowed to decide.</p><h2 id="primary-sources" tabindex="-1">Primary sources <a class="header-anchor" href="#primary-sources" aria-label="Permalink to &quot;Primary sources&quot;">​</a></h2><ul><li><a href="https://joinwell52-ai.github.io/joinwell52/en/publications/tmpa-core-specification-s1.0" target="_blank" rel="noreferrer">TMPA Core Specification S1.0</a></li><li><a href="https://joinwell52-ai.github.io/joinwell52/en/publications/implementation-case-i1.0" target="_blank" rel="noreferrer">Implementation Case I1.0</a></li><li><a href="https://github.com/joinwell52-AI/FCoP/blob/a859e6747fe6e5e2d686e0114c77774726d7f748/spec/fcop-v3-spec.md" target="_blank" rel="noreferrer">FCoP v3 specification</a></li><li><a href="https://pubs.opengroup.org/onlinepubs/9799919799/functions/rename.html" target="_blank" rel="noreferrer">POSIX rename</a></li><li><a href="https://apple.github.io/foundationdb/testing.html" target="_blank" rel="noreferrer">FoundationDB Simulation and Testing</a></li></ul>`,57))])}const k=i(d,[["render",c]]);export{b as __pageData,k as default};
